   */
  function clearTripleToSelfSigned() {
    const alive = lifetime.current;
    const base = committed.current;
    if (!alive?.value || base === null || inFlight.current) return;
    const cleared = { tlsCertFile: "", tlsKeyFile: "", tlsCaCertFile: "" };
