/**
 * dsh-lan-proxy — 客户端路由契约（issue #911）。
 *
 * 与宿主 ROUTES（src/server/config/impl/routes.ts）同值的镜像：两边各写一份的
 * 失败形态是静默的（对不上只表现成请求 404），故两端一致性由单测锁定
 * （CLIENT_ROUTES 与宿主 ROUTES 值全等，见 test/unit/unit-cacert.test.ts）。
 *
 * 构建期 __DSH_ROUTES__ 存在时优先取注入值（bundle-host extraDefine）；非 bundle
 * 环境（单测/源码直引）回落本地镜像——typeof 守卫写法抄 worktree-sidebar
 * （declare const 只活在类型层，裸引用在非 bundle 下 ReferenceError）。
 */
export const CLIENT_ROUTES = {
  config: "/api/dsh-lan-proxy/config",
  health: "/api/dsh-lan-proxy/health",
  caCert: "/api/dsh-lan-proxy/ca-cert",
  /** 一键 CA 动作（POST 只写；#930 Phase 2）：与宿主 ROUTES.caGenerate 同值（单测锁定）。 */
  caGenerate: "/api/dsh-lan-proxy/ca/generate",
} as const;

/** 构建期注入的宿主路由表（bundle-host extraDefine；缺席即 undefined）。 */
declare const __DSH_ROUTES__: Record<string, string> | undefined;

/** 取注入值（非字符串/缺席即回落镜像，保证永远是可用字符串）。 */
function injected(key: "config" | "health" | "caCert" | "caGenerate", fallback: string): string {
  if (typeof __DSH_ROUTES__ !== "undefined") {
    const value = __DSH_ROUTES__[key];
    if (typeof value === "string" && value.length > 0) return value;
  }
  return fallback;
}

/** 卡片实际使用的路由表（注入优先，镜像兜底）。 */
export const APP_ROUTES: {
  readonly config: string;
  readonly health: string;
  readonly caCert: string;
  readonly caGenerate: string;
} = {
  config: injected("config", CLIENT_ROUTES.config),
  health: injected("health", CLIENT_ROUTES.health),
  caCert: injected("caCert", CLIENT_ROUTES.caCert),
  caGenerate: injected("caGenerate", CLIENT_ROUTES.caGenerate),
};

packages/dsh-lan-proxy/src/client/ca-sta.source:
/**
 * dsh-lan-proxy — 一键 CA 客户端提醒判定（issue #930 F8 展示层）。
 *
 * 纯函数：health.certInfo 快照 → 到期 / IP 变化提醒。到期阈值 30 天（复用
 * certStillValid 口径风格：剩余有效期与阈值比较）。解析不出即不提醒
 * （展示层 fail-open；下发端仍按三态如实 404，不依赖本判定）。
 */

/** 叶子到期提醒阈值（毫秒）：剩余有效期低于 30 天即提醒轮换。 */
export const LEAF_EXPIRY_WARN_MS = 30 * 86400 * 1000;

/** certInfo 读子集（health 快照经 HTTP 后的形态；缺键容错）。 */
export interface CertInfoView {
  leafValidTo?: unknown;
  leafSans?: unknown;
  currentIps?: unknown;
}

/** 提醒结果（调用方按 httpsEnabled 与 caState 决定是否渲染）。 */
export interface CaWarnings {
  expiring: boolean;
  ipChanged: boolean;
}

/**
 * X509 subjectAltName 原串中的 IP 条目（"IP Address:1.2.3.4" 前缀；DNS 条目
 * 与非字符串一律忽略——丢弃未知形态，不抛错）。
 */
export function sanIps(sans: unknown): string[] {
  if (!Array.isArray(sans)) return [];
  const prefix = "IP Address:";
  const out: string[] = [];
  for (const entry of sans) {
    if (typeof entry === "string" && entry.startsWith(prefix)) {
      out.push(entry.slice(prefix.length));
    }
  }
  return out;
}

/**
 * 提醒判定：到期（validTo 可解析且剩余 < 30 天）与 IP 变化（当期非回环 IP
 * 存在未被 SAN 覆盖者；当期为空即无法判断，不提醒）。
 */
export function evaluateCaWarnings(info: CertInfoView, nowMs: number): CaWarnings {
  let expiring = false;
  if (typeof info.leafValidTo === "string") {
    const validTo = Date.parse(info.leafValidTo);
    if (!Number.isNaN(validTo)) expiring = validTo - nowMs < LEAF_EXPIRY_WARN_MS;
  }
  const current = Array.isArray(info.currentIps)
    ? info.currentIps.filter((ip): ip is string => typeof ip === "string")
    : [];
  const covered = new Set(sanIps(info.leafSans));
  return { expiring, ipChanged: current.length > 0 && current.some((ip) => !covered.has(ip)) };
}

packages/dsh-lan-proxy/src/client/host-t.source:
/**
 * dsh-lan-proxy — 客户端 host trust 观测（issue #856）。
 *
 * 宿主端注入（src/server/host-trust/impl/injection.ts）让非回环页面声明 `ownsHost`，从而恢复被上游按
 * `isLoopback` 降级掉的 Host 设置持久化面。本模块把「这个注入到底有没有生效」
 * 变成可观测事实——只看文字声明发现不了上游把 `ownsHost` 从 isLoopback 谓词里
 * 删掉/改名/重排。
 *
 * 三段判定用三个信号，缺一不可：
 * 1. `location.hostname`——区分「本机页面」与「非回环页面」：兼容模式下
 *    isLoopback 同为 true，光看它无法区分两者；
 * 2. 注入脚本落的 marker（`__DSH_LAN_PROXY_HOST_TRUST__`）——宿主侧注入是否真的
 *    落到了本页；
 * 3. 公开事实 `ctx.remote.$host.isLoopback`——上游是否据此把本页判为 Host 独占。
 *
 * 判定逻辑是纯函数（进 test/client-unit，不依赖 DOM），信号读取单独一个函数；
 * 调用侧（设置卡片）必须整段降级为 warn——client 插件 apply 抛错会影响页面启动。
 */

/** 兼容注入脚本在页面里落下的 marker（值与宿主端 HOST_TRUST_RUNTIME_MARKER 同源）。 */
export const HOST_TRUST_RUNTIME_MARKER = "__DSH_LAN_PROXY_HOST_TRUST__";

/**
 * ctx.remote 的防御式最小面（dsh 客户端 Typert Remote 网关）：
 * 仅声明本观测器消费的公开事实 `$host.isLoopback`。官方类型层不在本包依赖面内，
 * 与 packages/dsh-provider-usage/src/client/core.ts 的 RemoteLike 同一做法。
 */
export interface RemoteLike {
  $host?: { isLoopback?: boolean };
}

/** 三段判定所需的三个信号（缺省即「未知」，判定按 fail-closed 处理）。 */
export interface HostTrustSignals {
  /** 页面 authority 的主机名（`location.hostname`；IPv6 字面量保留方括号）。 */
  hostname?: string;
  /** 注入脚本是否真的写入过 transport。 */
  marker?: boolean;
  /** 上游公开事实：本页是否被判定为 Host 独占。 */
  isLoopback?: boolean;
}

/**
 * 观测到的四种状态：
 * - `loopback-page`：本机页（回环 authority，或上游已有 transport 声明 ownsHost 的
 *   宿主独占页）——设置持久化面正常，无需本开关，也不该告警；
 * - `compat-active`：非回环页 + marker 在 + `isLoopback` 为 true——兼容模式生效；
 * - `contract-drift`：非回环页 + marker 在 + `isLoopback` 仍非 true——上游契约已
 *   漂移（或 `ctx.remote` 不可读），显式告警，不静默；
 * - `compat-off`：非回环页 + marker 不在——开关关闭（或本页未被注入），设置面被
 *   上游降级为 memory scope。
 */
export type HostTrustStatus = "loopback-page" | "compat-active" | "contract-drift" | "compat-off";

/** 状态 → 设置卡片 i18n key（判定与展示分离：判定进变异面，文案留字典）。 */
export const HOST_TRUST_STATUS_KEY: Record<HostTrustStatus, string> = {
  "loopback-page": "hostTrustStatusLoopback",
  "compat-active": "hostTrustStatusCompat",
  "contract-drift": "hostTrustStatusDrift",
  "compat-off": "hostTrustStatusOff",
};

/**
 * 与上游 isLoopbackHostname 同口径的回环判据：`localhost` / `[::1]` / 整个 127/8。
 * 不用 `URL`：`location.hostname` 已是规范化后的主机名，再解析一次只会引入
 * 「空串/相对形式」这类无意义分支。
 */
export function isLoopbackHostname(hostname: string | undefined): boolean {
  if (hostname === "localhost" || hostname === "[::1]") return true;
  if (typeof hostname !== "string") return false;
  const parts = hostname.split(".");
  return (
    parts.length === 4 &&
    parts[0] === "127" &&
    parts.every((part) => /^\d{1,3}$/.test(part) && Number(part) <= 255)
  );
}

/**
 * 三段判定的纯函数形态（表驱动判据的唯一被测对象）。
 *
 * @param signals - 三个观测信号。
 * @returns 四种状态之一。
 */
export function evaluateHostTrust(signals: HostTrustSignals): HostTrustStatus {
  if (isLoopbackHostname(signals.hostname)) return "loopback-page";
  if (signals.marker !== true) {
    // 非回环页却没有 marker：上游可能已自带 transport（desktop-host 一类宿主独占
    // 页，isLoopback 已为 true）——那是正常态，不是「开关关闭」。
    return signals.isLoopback === true ? "loopback-page" : "compat-off";
  }
  // marker 在但上游仍不认：契约漂移（isLoopback 未知同样按漂移告警，fail-closed）。
  return signals.isLoopback === true ? "compat-active" : "contract-drift";
}

/**
 * 四态判定 → 控制台告警文案（`null` = 该状态不告警）。
 *
 * 为什么需要这条独立出口：唯一详细渲染面是插件行配置页，而它受 Host authority 与
 * settings namespace 投影约束；`compat-off` 与 `contract-drift` 下页面可能不可用。
 * 同一枚 isLoopback 信号既影响配置持久化、又决定判定结果，越是需要解释故障时越不能依赖
 * 配置页本身。devtools 控制台是不依赖配置面、又随手可得的可见面
 * （issue #856 的原始排查方式）。文案与判定分离，函数保持纯函数形态以便表驱动单测。
 *
 * @param status - `evaluateHostTrust` 的判定结果。
 * @returns 告警正文（调用方补 `[dsh-lan-proxy]` 前缀），无告警时为 null。
 */
export function hostTrustAlert(status: HostTrustStatus): string | null {
  if (status === "contract-drift") {
    return (
      "host trust 契约漂移：注入 marker 已在页面上，但上游 isLoopback 仍非 true——" +
      "兼容注入很可能已失效，设置持久化面仍被上游降级，请按 dsh-upgrade 流程复核"
    );
  }
  if (status === "compat-off") {
    return (
      "host trust 兼容未生效：本页为非回环 authority 且未落注入 marker，上游把设置面降级为 " +
      "memory scope（设置不可持久化）。最常见原因是 ownsHostCompat 为默认关；需要时在" +
      "插件管理器的 dsh-lan-proxy 行详情中开启，或直接编辑 settings.yaml，或改用 ssh -L 走回环"
    );
  }
  return null;
}

/**
 * 读取运行期信号。DOM/全局访问集中在这里，使上面的判定在 node 环境可直接跑。
 *
 * @param remote - 客户端 ctx.remote（未声明 inject 或服务缺失时为 undefined）。
 */
export function readHostTrustSignals(remote: RemoteLike | undefined): HostTrustSignals {
  const nav = typeof globalThis.location === "undefined" ? undefined : globalThis.location;
  return {
    hostname: nav === undefined ? undefined : nav.hostname,
    marker: (globalThis as unknown as Record<string, unknown>)[HOST_TRUST_RUNTIME_MARKER] === true,
    isLoopback: remote?.$host?.isLoopback,
  };
}

packages/dsh-lan-proxy/test/client-dom/s.source:
// @vitest-environment happy-dom
/**
 * 真实 React 卡片经浏览器 fetch 接缝测试；手写替身只记录请求、交付响应。
 * act 排空 Promise，计时器用显式假钟推进，不访问真实网络或设置存储。
 */
import * as React from "react";
import { act, cleanup, fireEvent, render } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { SettingsCard } from "../../src/client/settings-card.tsx";

const originalFetch = globalThis.fetch;
let writes: unknown[];
let reply: () => Promise<Response>;
let initial: unknown;
let health: unknown;
let requests: string[];
function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status });
}
function deferred() {
  let resolve!: (response: Response) => void;
  const promise = new Promise<Response>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}
let caWrites: unknown[];
let caReply: () => Promise<Response>;
beforeEach(() => {
  writes = [];
  caWrites = [];
  initial = { effective: { port: 4000 }, user: {}, revision: 0 };
  health = {};
  requests = [];
  reply = async () => json({ ok: true, revision: 1 });
  caReply = async () => json({ ok: true, mode: "generated" });
  globalThis.fetch = async (input, init) => {
    if (init?.method === "PUT") {
      writes.push(JSON.parse(String(init.body)));
      return reply();
    }
    if (init?.method === "POST") {
      caWrites.push(JSON.parse(String(init.body)));
      return caReply();
    }
    if (init?.method === undefined) requests.push(String(input));
    return json(String(input).endsWith("/config") ? initial : health);
  };
});
afterEach(() => {
  cleanup();
  globalThis.fetch = originalFetch;
  vi.useRealTimers();
});
const card = (view: "summary" | "page" = "page") =>
  React.createElement(SettingsCard, {
    view,
    hostTrustSignals: () => ({ hostname: "localhost" }),
  });
async function mountRowEntry(view: "summary" | "page") {
  const ownerKey = "@wingsky-1/dsh-lan-proxy#dsh-lan-proxy";
  const host =
    view === "summary"
      ? React.createElement("p", { "data-plugin-row-detail": ownerKey }, card(view))
      : React.createElement("div", { "data-plugin-config": true }, card(view));
  const rendered = render(host);
  await act(async () => {});
  return rendered;
}

async function mountCard(view: "summary" | "page" = "page") {
  return mountRowEntry(view);
}
type View = Awaited<ReturnType<typeof mountCard>>;
function save(view: View) {
  fireEvent.click(view.getByRole("button", { name: "save" }));
}
function port(view: View, value: string) {
  fireEvent.change(view.getByLabelText("lanPort"), { target: { value } });
}

describe("SettingsCard row view 契约", () => {
  it("summary 在官方描述容器内只返回非-li 摘要，不请求 config/health", async () => {
    const view = await mountRowEntry("summary");
    const summary = view.container.querySelector("[data-lan-summary]");
    expect(requests).toEqual([]);
    expect(view.container.querySelector("li")).toBe(null);
    expect(summary?.tagName).toBe("SPAN");
    expect(summary?.parentElement?.tagName).toBe("P");
    expect(summary?.textContent).toBe("settingsDescription");
  });

  it("page 直接使用非-li wrapper 显示字段和保存控件，各加载一次 config/health", async () => {
    const view = await mountRowEntry("page");
    const page = view.container.querySelector("[data-lan-page]");
    expect(page?.tagName).toBe("DIV");
    expect(view.container.querySelector("li")).toBe(null);
    expect(view.container.querySelector(".lp-set-body")).toBeTruthy();
    expect(view.container.querySelector(".lp-set-head")).toBe(null);
    expect(view.queryByText("settingsName")).toBe(null);
    expect(view.queryByText("settingsDescription")).toBe(null);
    const portInput = view.getByLabelText("lanPort") as HTMLInputElement;
    const saveButton = view.getByRole("button", { name: "save" }) as HTMLButtonElement;
    expect(portInput.disabled).toBe(false);
    expect(saveButton.disabled).toBe(false);
    expect(requests).toEqual(["/api/dsh-lan-proxy/config", "/api/dsh-lan-proxy/health"]);
  });
});

describe("SettingsCard 输入与显示契约", () => {
  it.each([
    ["enable", "enabled", true],
    ["httpsCoexist", "httpsEnabled", true],
    ["printBanner", "printBanner", true],
    ["wsBridge", "wsBridgeEnabled", true],
    ["wsCompress", "wsCompressEnabled", true],
    ["httpCompress", "httpCompressEnabled", true],
    ["injectToken", "injectToken", true],
    ["ownsHostCompat", "ownsHostCompat", false],
  ] as const)("%s 默认值与开关写回", async (label, key, checked) => {
    initial = { revision: 0 };
    const view = await mountCard();
    const input = view.getByLabelText(label) as HTMLInputElement;
    expect(input.checked).toBe(checked);
    fireEvent.click(input);
    expect(input.checked).toBe(!checked);
    save(view);
    expect(writes).toEqual([{ patch: { [key]: !checked }, expectedRevision: 0 }]);
    await act(async () => {});
  });
  it.each([
    ["httpsPort", "httpsPort", "4443", 4443],
    ["certFile", "tlsCertFile", "/tmp/cert.pem", "/tmp/cert.pem"],
    ["keyFile", "tlsKeyFile", "/tmp/key.pem", "/tmp/key.pem"],
    ["caCertFile", "tlsCaCertFile", "/tmp/ca.pem", "/tmp/ca.pem"],
    ["compressLevel", "httpCompressLevel", "3", 3],
    ["wsPaths", "wsCompressPaths", " /a, , /b ", ["/a", "/b"]],
  ] as const)("%s 只写对应字段", async (label, key, text, value) => {
    const view = await mountCard();
    fireEvent.change(view.getByLabelText(label), { target: { value: text } });
    save(view);
    expect(writes).toEqual([{ patch: { [key]: value }, expectedRevision: 0 }]);
    await act(async () => {});
  });
  it.each(["0", "65536", "1.5"])("非法HTTP端口%s零请求", async (value) => {
    const view = await mountCard();
    port(view, value);
    save(view);
    expect(view.getByText("portRangeFail").className).toBe("lp-set-error");
    expect(writes).toEqual([]);
  });
  it.each(["0", "65536", "1.5"])("非法HTTPS端口%s零请求", async (value) => {
    const view = await mountCard();
    fireEvent.change(view.getByLabelText("httpsPort"), { target: { value } });
    save(view);
    expect(view.getByText("httpsPortRangeFail").className).toBe("lp-set-error");
    expect(writes).toEqual([]);
  });
  it.each([-1, 4, 1.5])("非法加载压缩档位%s不能保存", async (value) => {
    initial = { effective: { httpCompressLevel: value }, revision: 0 };
    const view = await mountCard();
    save(view);
    expect(view.getByText("levelRangeFail").className).toBe("lp-set-error");
    expect(writes).toEqual([]);
  });
  it("默认端口和压缩值、用户层优先与告警显隐", async () => {
    initial = { effective: { port: 4400 }, user: { port: 4500 }, revision: 0 };
    const view = await mountCard();
